import json
from orca_task_sdk import run_orca

req_key = 'ethanol_opt_freq'
receipt = run_orca('job.inp', dependencies=('ethanol.xyz',), request_key=req_key)
files = receipt.get('files', {}) or {}

def read_file(name):
    p = files.get(name)
    if not p:
        return ''
    with open(p, 'r', errors='replace') as f:
        return f.read()

stdout = read_file('stdout.out')
xyz_text = read_file('job.xyz')

freqs = []
for line in stdout.splitlines():
    s = line.strip()
    if 'cm**-1' not in s or ':' not in s:
        continue
    left, right = s.split(':', 1)
    if not left.strip().isdigit():
        continue
    parts = right.strip().split()
    if not parts:
        continue
    try:
        val = float(parts[0])
    except Exception:
        continue
    if val == val and abs(val) != float('inf'):
        freqs.append(val)

obs = [
    {
        'name': 'optimized_geometry',
        'value': xyz_text,
        'unit': 'angstrom',
        'sources': [{'filename': 'job.xyz', 'location': None, 'internal_request_key': req_key}] if xyz_text else [],
        'limitations': [] if xyz_text else ['Final optimized XYZ not found among returned files.']
    },
    {
        'name': 'vibrational_frequencies',
        'value': freqs,
        'unit': 'cm^-1',
        'sources': [{'filename': 'stdout.out', 'location': 'frequency block', 'internal_request_key': req_key}] if freqs else [],
        'limitations': [] if freqs else ['Could not locate a complete frequency list in returned stdout.out.']
    }
]
with open('observations.json', 'w') as f:
    json.dump({'version': 1, 'observations': obs}, f, indent=2)
print(json.dumps({'operation_status': receipt.get('operation_status'), 'files': sorted(files.keys())}))

